import{_ as o,o as e,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Rise of the AI Programmer- Implications for Ceph","description":"","frontmatter":{"title":"Rise of the AI Programmer- Implications for Ceph","date":"2026-07-10T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["社区动态","会议纪要","开源","自动化","CI/CD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Rise_of_the_AI_Programmer_-_Implications_for_Ceph.md","filePath":"posts/2026/Rise_of_the_AI_Programmer_-_Implications_for_Ceph.md","lastUpdated":null}'),n={name:"posts/2026/Rise_of_the_AI_Programmer_-_Implications_for_Ceph.md"};function a(l,t,s,g,p,h){return e(),r("div",null,[...t[0]||(t[0]=[i('<h2 id="演讲背景与引言" tabindex="-1">演讲背景与引言 <a class="header-anchor" href="#演讲背景与引言" aria-label="Permalink to &quot;演讲背景与引言&quot;">​</a></h2><p>演讲者 Ernesto 曾担任 Ceph Dashboard 组件负责人，目前专注于研究 AI 在软件工程（SE）及开源项目中的角色。演讲以一段历史故事开场：15 年前他在剑桥一家初创公司接触到 Edward Jordan 的经典著作，该书写于 1990 年代初期，核心论点是美国程序员比印度和日本同行贵五倍、生产力更低、更懒散、更个人主义、更容易犯错——因此美国 IT 产业面临严峻威胁。</p><p>将这个论点平移到 2026 年，他认为人类程序员与 AI 编程 agent 之间的对比惊人地相似：AI agent 成本优势尚不明确、生产力（以代码行数衡量）更高、全年无休、没有 ego 问题，但同样会犯错（即&quot;幻觉&quot;，hallucination）。</p><h2 id="ai-agent-的基本架构" tabindex="-1">AI Agent 的基本架构 <a class="header-anchor" href="#ai-agent-的基本架构" aria-label="Permalink to &quot;AI Agent 的基本架构&quot;">​</a></h2><p>当前我们日常使用的 AI 工具——ChatGPT、Cursor、GitHub Copilot——本质上都是 <strong>agent</strong>，而不是裸模型。一个完整的 agent 架构包含：</p><ul><li><strong>LLM</strong>：核心推理组件</li><li><strong>Memory</strong>：上下文记忆</li><li><strong>Tools</strong>：外部工具调用能力</li><li><strong>Planning/Task 模块</strong>：基于用户 prompt 自动拆解任务</li></ul><h2 id="ai-在-ceph-社区的现状" tabindex="-1">AI 在 Ceph 社区的现状 <a class="header-anchor" href="#ai-在-ceph-社区的现状" aria-label="Permalink to &quot;AI 在 Ceph 社区的现状&quot;">​</a></h2><h3 id="pr-代码审查的采用情况" tabindex="-1">PR 代码审查的采用情况 <a class="header-anchor" href="#pr-代码审查的采用情况" aria-label="Permalink to &quot;PR 代码审查的采用情况&quot;">​</a></h3><p>目前在 Ceph 开发生命周期中，AI 最可见的切入点是 <strong>pull request review</strong>，因为 GitHub 会自动创建相关数据。过去一年，GitHub Copilot 对 Ceph PR 的月度审查数量增长了约 5 倍。</p><p>使用方式：</p><ul><li>手动：在 PR 中将 Copilot 添加为 reviewer，几分钟内即可获得审查结果</li><li>自动（个人设置）：在个人 profile 中开启，所有 PR 自动被审查，token 消耗计入个人配额</li><li>仓库级 branch rule（尚未在 Ceph 仓库启用，需进一步讨论）</li></ul><p>值得注意的是，一年前 Copilot 甚至无法分析 C++ PR，如今已能识别并讨论并发（concurrency）、线程等复杂问题，尽管有时分析结论有误，但质量已远超静态分析工具。</p><h3 id="ceph-社区关于-ai-的政策讨论" tabindex="-1">Ceph 社区关于 AI 的政策讨论 <a class="header-anchor" href="#ceph-社区关于-ai-的政策讨论" aria-label="Permalink to &quot;Ceph 社区关于 AI 的政策讨论&quot;">​</a></h3><p>目前有一个已开放六个月的 PR，核心要点包括：</p><ol><li><strong>LLM 生成或辅助的代码不被禁止</strong>，各组件可自行设定更严格的要求</li><li><strong>需要披露 AI 使用情况</strong>，倾向采用类似 Linux kernel 的方式：<code>Assisted-by: &lt;模型名称+版本&gt;</code></li><li><strong>不强制提交 prompt</strong>，因为模型非确定性，相同 prompt 不会产生相同输出</li><li><strong>人类仍对 AI 产出的代码负责</strong>，贡献者必须是代码的 owner，这也与 DCO（Developer Certificate of Origin）要求一致</li></ol><h2 id="定制-agent-行为的五种方式" tabindex="-1">定制 Agent 行为的五种方式 <a class="header-anchor" href="#定制-agent-行为的五种方式" aria-label="Permalink to &quot;定制 Agent 行为的五种方式&quot;">​</a></h2><ol><li><strong>Custom Instructions</strong>：针对 Copilot，在仓库中添加指令文件，所有 prompt 将遵循该策略</li><li><strong>AGENTS.md 文件</strong>（或类似标准文件）：Anthropic 等厂商正在推动跨 agent/模型的统一规范文件</li><li><strong>MCP Servers</strong>：为模型提供实时环境上下文。由于模型知识是固定的，MCP server 是让模型感知当前环境的关键机制。建议考虑接入： <ul><li>GitHub MCP（自动提供相关 issue、PR 上下文）</li><li>Redmine MCP（从 tracker 获取历史数据）</li><li>Teuthology MCP（从测试运行获取新鲜数据，目前有非官方实现）</li></ul></li><li><strong>Skills</strong>：无需单独部署的自包含 artifact，粒度比 instructions 更细。例如可以定义一个专门检查 PR/commit 是否符合 Ceph 贡献规范的 skill</li><li><strong>Custom Agents（子 agent）</strong>：解决 context window 限制问题。主 agent 启动专注于特定任务的子 agent（如安全审查 agent），子 agent 完成后返回结果，避免污染主 agent 的上下文</li></ol><p>此外还有 <strong>Hooks</strong>，可在 agent 生命周期中注入回调，主要用于审计和调试。</p><h2 id="prompt-engineering-要点" tabindex="-1">Prompt Engineering 要点 <a class="header-anchor" href="#prompt-engineering-要点" aria-label="Permalink to &quot;Prompt Engineering 要点&quot;">​</a></h2><ol><li><strong>使用英语</strong>：英语的 token 效率最高（约 3-4 个字母一个 token），西班牙语约低 50%，非拉丁文字语言（如希腊语）可能多消耗 6 倍 token；且模型在英语上训练最充分，输出质量更高</li><li><strong>避免过度礼貌</strong>：礼貌语气可能触发模型的&quot;讨好&quot;模式（sycophancy），导致给出好听而非正确的答案；应直接、清晰地发出指令</li><li><strong>Grounding（接地）</strong>：提供具体示例、输入输出样例、枚举列表，而非抽象描述</li><li><strong>使用紧凑数据格式</strong>：避免 JSON（括号等符号占用额外 token），推荐 YAML、Markdown 或类 CSV 格式</li><li><strong>Spec-Driven Development（SDD）</strong>：所有 prompt 和中间 artifact（spec.md、plan、tasks）都应版本化并存入 git，代码成为&quot;编译产物&quot;，规格文件成为新的源代码</li></ol><h2 id="人机协作的三种模式" tabindex="-1">人机协作的三种模式 <a class="header-anchor" href="#人机协作的三种模式" aria-label="Permalink to &quot;人机协作的三种模式&quot;">​</a></h2><ol><li><strong>Human in the Loop</strong>：人类深度介入每个环节（需求、计划、审查），AI 提供辅助</li><li><strong>Human on the Loop</strong>：人类参与初始需求定义，之后以审批方式介入，大幅减少直接参与</li><li><strong>Human at the Edge</strong>：人类仅负责定义规格（spec），后续由 AI pipeline 完成所有步骤，最终校验输出是否与规格对齐（intent-based 验证），而非逐行审查代码正确性</li></ol><h2 id="安全性挑战" tabindex="-1">安全性挑战 <a class="header-anchor" href="#安全性挑战" aria-label="Permalink to &quot;安全性挑战&quot;">​</a></h2><p>近期安全漏洞报告数量激增，可能与 AI 辅助漏洞发现有关（如 Anthropic 的 Mythos 项目相关工作）。对 Ceph 而言：</p><ul><li>安全团队（目前主要是 Sage Maktagar）可能面临报告数量过载的压力</li><li>白帽报告增加的同时，恶意利用风险同样上升</li></ul><p><strong>AI 辅助故障排查</strong>的架构设想：</p><ul><li>接入 Ceph MCP server、Prometheus MCP、日志 MCP，采集集群状态</li><li>在向量数据库或知识库中搜索相似历史 issue 和文档</li><li>将聚合信息输入 LLM 进行多轮推理，定位根因</li></ul><h2 id="短期挑战" tabindex="-1">短期挑战 <a class="header-anchor" href="#短期挑战" aria-label="Permalink to &quot;短期挑战&quot;">​</a></h2><ul><li><strong>AI Slop（低质量输出）</strong>：模型幻觉和输出质量不稳定，需要明确的 AI 使用政策，规定哪些 artifact（单元测试、文档、核心代码）可以接受 AI 辅助</li><li><strong>法律合规</strong>：需确保 AI 生成代码不违反许可证（如 LGPL），建议运行代码相似性检测工具</li><li><strong>安全风险</strong>：Prompt injection 攻击——恶意 PR 中可能隐藏触发 agent 执行恶意操作的 prompt。建议： <ul><li>所有 AI agent 必须在沙箱中运行</li><li>CI pipeline 中的 AI 组件需严格隔离</li></ul></li></ul><h2 id="长期挑战" tabindex="-1">长期挑战 <a class="header-anchor" href="#长期挑战" aria-label="Permalink to &quot;长期挑战&quot;">​</a></h2><ul><li><strong>Vendor Lock-in</strong>：LLM 目前主要以 SaaS 形式提供，一旦依赖则形成强耦合。建议保持多模型策略（multi-model），使用开放标准，期待 Linux Foundation 等机构推动真正开源的 LLM</li><li><strong>Developer Detachment（开发者疏离感）</strong>：开源社区中代码不只是工作，更是热情所在。AI 替代编码工作可能导致贡献者失去参与感，需保持&quot;以人为中心&quot;的开源精神，AI 应作为助手而非主导者</li><li><strong>就业影响</strong>：据《经济学人》报道，IT 从业者就业率已下降约 4%，初级工程师受影响尤为明显。社区可能需要考虑为初级工程师设立参与配额，以维护人才梯队</li></ul><h2 id="结语与乐观展望" tabindex="-1">结语与乐观展望 <a class="header-anchor" href="#结语与乐观展望" aria-label="Permalink to &quot;结语与乐观展望&quot;">​</a></h2><p>Edward Jordan 在《美国程序员的没落》出版四年后写了续集《美国程序员的崛起与复兴》，指出正是那些被批评的特质——个人主义、打破常规的精神——催生了硅谷的创业浪潮。</p><p>类比当下，人类程序员拥有 LLM 目前缺乏的能力：</p><ul><li><strong>意图理解</strong>（intent），而非仅仅是 token 模式匹配</li><li><strong>端到端系统理解</strong>，而非局部视野</li><li><strong>权衡取舍的判断力</strong></li><li><strong>法律责任与问责制</strong></li><li><strong>项目的长期所有权</strong></li></ul><p>AI 不会立即取代程序员，但<strong>由更具 AI 技能的团队驱动的项目，将明显超越那些不拥抱这些实践的项目</strong>。Ceph 社区需要认真对待这一话题，即便决定在某些领域保持人工主导，也必须将这场对话提上日程。</p>',36)])])}const d=o(n,[["render",a]]);export{c as __pageData,d as default};
